export const techMap = new Map<string, TechItem>();
techRegistry.forEach((item) => {
  techMap.set(item.name.toLowerCase(), item);
  techMap.set(item.slug.toLowerCase(), item);
});

export function getTechItem(nameOrSlug: string): TechItem | undefined {
  const normalized = nameOrSlug.trim().toLowerCase();
  if (techMap.has(normalized)) return techMap.get(normalized);

  // Partial match fallback
  for (const [key, item] of techMap.entries()) {
    if (normalized.includes(key) || key.includes(normalized)) {
      return item;
    }
  }
  return undefined;
}
